mapper.select:
SELECT a.id, a.password_hash, a.status = 'ENABLED' AS enabled, a.credential_version, r.code AS role_code

WHERE a.phone = #{phone}
ORDER BY FIELD(r.code, 'SUPER_ADMIN', 'EVENT_OPERATOR', 'CHECKIN_STAFF')

SELECT a.phone, a.status = 'ENABLED' AS enabled, a.credential_version, r.code AS role_code

WHERE a.id = #{id}
ORDER BY FIELD(r.code, 'SUPER_ADMIN', 'EVENT_OPERATOR', 'CHECKIN_STAFF')
